(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const w2x = Math.sin(x*0.008-t*0.15)*25 + Math.cos(y*0.012+t*0.1)*18;
  const w2y = Math.cos(y*0.009+t*0.12)*22 + Math.sin(x*0.011-t*0.18)*16;
  const sx = x + w1x + w2x*0.5, sy = y + w1y + w2y*0.5;
  const s2x = x + w2x + w1x*0.3, s2y = y + w2y + w1y*0.3;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.14, 2.1, 0.8],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*45, 0.11, 1.8, 1.15]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d1 = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const d2 = Math.sqrt((s2x-sX)**2+(s2y-sY)**2);
    aS += Math.sin(d1*f - t*sp)*w;
    iS += Math.sin(d1*f*0.7 + t*sp*0.6 + 1.5)*w;
    aS2 += Math.sin(d2*f*1.4 - t*sp*0.8 + 0.5)*w;
    iS2 += Math.sin(d2*f*0.5 + t*sp*0.4 + 2.8)*w;
  }
  const n = 8;
  const act=aS/n, inh=iS/n, act2=aS2/n, inh2=iS2/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const moire = Math.sin(dist*0.08)*Math.sin(ang*5+t*0.7)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((act2 - inh2*0.6 + moire + bg*0.2)*1.8);
  const cross = rd1*rd2;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.tanh(Math.sin(sx*0.3+t*1.2)*Math.sin(sy*0.35-t*0.9)*2)*0.15;
  const pulse = 0.85+Math.sin(t*0.4)*0.15;
  const blend = rd1*0.4 + rd2*0.25 + cross*0.2 + cell*0.1 + micro*0.05;
  const v = blend*pulse*0.5+0.5;
  const edge1 = 1-Math.min(1, Math.abs(rd1)*4)*0.15;
  const edge2 = 1-Math.min(1, Math.abs(cross)*5)*0.1;
  const pal = [
    [6,12,52],[12,42,88],[18,85,118],[25,138,135],[55,168,125],
    [140,188,95],[205,195,75],[225,165,65],[215,120,75],[185,70,70],
    [140,40,65],[90,22,58],[45,15,50],[6,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum = 0.85+Math.sin(blend*Math.PI)*0.15;
  const edge = edge1*edge2;
  const glow = Math.max(0, cross)*0.3;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*60)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*100)|0)
  ];
}
